import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mostExpensiveItem } from '../src/cart.js';

test('mostExpensiveItem picks the first item on a price tie', () => {
  const items = [
    { name: 'a', price: 10 },
    { name: 'b', price: 10 },
  ];
  assert.equal(mostExpensiveItem(items).name, 'a');
});

